class Machine:
    """States: IDLE (no money) and PAID (money inserted). Selling returns to IDLE."""

    def __init__(self):
        self.items = {}                # name -> [price, qty]
        self.state = "IDLE"
        self.credit = 0

    def stock(self, name, price, qty):
        if name in self.items:
            self.items[name][1] += qty
        else:
            self.items[name] = [price, qty]
        return f"{name}: {self.items[name][1]} at {self.items[name][0]}"

    def insert(self, amount):
        self.credit += amount
        self.state = "PAID"
        return f"credit {self.credit}"

    def select(self, name):
        # TODO: refuse in IDLE, refuse unavailable items and too little credit; else dispense with change.
        return f"dispense {name}, change 0"

    def cancel(self):
        # TODO: return the credit and go back to IDLE.
        return "nothing to refund"

import sys

from machine import Machine


def num(s):
    return int(s) if s.isdigit() and 0 < int(s) <= 10000 else None


def main():
    m = Machine()
    for raw in sys.stdin:
        p = raw.split()
        if not p:
            continue
        if p[0] == "STOCK" and len(p) == 4 and num(p[2]) and num(p[3]):
            print(m.stock(p[1], num(p[2]), num(p[3])))
        elif p[0] == "INSERT" and len(p) == 2 and p[1] in ("1", "2", "5", "10", "20", "50", "100"):
            print(m.insert(int(p[1])))
        elif p[0] == "SELECT" and len(p) == 2:
            print(m.select(p[1]))
        elif p[0] == "CANCEL" and len(p) == 1:
            print(m.cancel())
        else:
            print(f"error: bad command {raw.strip()}")


main()

