    def insert(self, amount):
        self.credit += amount
        self.state = "PAID"
        return f"credit {self.credit}"

    def select(self, name):
        if self.state == "IDLE":
            return "error: insert money first"
        item = self.items.get(name)
        if item is None or item[1] == 0:
            return f"error: {name} unavailable"
        price = item[0]
        if self.credit < price:
            return f"error: need {price - self.credit} more"
        item[1] -= 1
        change = self.credit - price
        self.credit, self.state = 0, "IDLE"
        return f"dispense {name}, change {change}"

    def cancel(self):
        if self.state == "IDLE":
            return "nothing to refund"
        refund, self.credit, self.state = self.credit, 0, "IDLE"
        return f"refund {refund}"

