class Machine {
    enum State { IDLE, PAID }
    final Map<String, int[]> items = new HashMap<>();   // name -> {price, qty}
    State state = State.IDLE;
    int credit = 0;

    String stock(String name, int price, int qty) {
        int[] it = items.computeIfAbsent(name, k -> new int[] {price, 0});
        it[1] += qty;
        return name + ": " + it[1] + " at " + it[0];
    }

    String insert(int amount) {
        credit += amount;
        state = State.PAID;
        return "credit " + credit;
    }

    String select(String name) {
        // TODO: refuse in IDLE, refuse unavailable items and too little credit; else dispense with change.
        return "dispense " + name + ", change 0";
    }

    String cancel() {
        // TODO: return the credit and go back to IDLE.
        return "nothing to refund";
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int num(String s) {
        return s.matches("\\d{1,5}") && Integer.parseInt(s) > 0 && Integer.parseInt(s) <= 10000 ? Integer.parseInt(s) : 0;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        Machine m = new Machine();
        List<String> coins = List.of("1", "2", "5", "10", "20", "50", "100");
        for (String raw; (raw = in.readLine()) != null; ) {
            String[] p = raw.trim().split("\\s+");
            if (p[0].isEmpty()) continue;
            String reply;
            if (p[0].equals("STOCK") && p.length == 4 && num(p[2]) > 0 && num(p[3]) > 0) reply = m.stock(p[1], num(p[2]), num(p[3]));
            else if (p[0].equals("INSERT") && p.length == 2 && coins.contains(p[1])) reply = m.insert(Integer.parseInt(p[1]));
            else if (p[0].equals("SELECT") && p.length == 2) reply = m.select(p[1]);
            else if (p[0].equals("CANCEL") && p.length == 1) reply = m.cancel();
            else reply = "error: bad command " + raw.trim();
            out.append(reply).append('\n');
        }
        System.out.print(out);
    }
}

