import java.util.*;

class Machine {
    enum State { IDLE, PAID }
    final Map<String, int[]> items = new HashMap<>();   // name -> {price, qty}
    State state = State.IDLE;
    int credit = 0;

    String stock(String name, int price, int qty) {
        int[] it = items.computeIfAbsent(name, k -> new int[] {price, 0});
        it[1] += qty;
        return name + ": " + it[1] + " at " + it[0];
    }

    String insert(int amount) {
        credit += amount;
        state = State.PAID;
        return "credit " + credit;
    }

    String select(String name) {
        if (state == State.IDLE) return "error: insert money first";
        int[] it = items.get(name);
        if (it == null || it[1] == 0) return "error: " + name + " unavailable";
        if (credit < it[0]) return "error: need " + (it[0] - credit) + " more";
        it[1]--;
        int change = credit - it[0];
        credit = 0;
        state = State.IDLE;
        return "dispense " + name + ", change " + change;
    }

    String cancel() {
        if (state == State.IDLE) return "nothing to refund";
        int refund = credit;
        credit = 0;
        state = State.IDLE;
        return "refund " + refund;
    }
}

